  --color-success: #0d813c;
  --color-warning: #734d06;
  --color-danger: #be302c;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-background: #181b20;
    --color-surface: #282b32;
    --color-text: #f3f7fe;
    --color-muted: #9da1ab;
    --color-border: #3c4047;
    --color-primary: #2449df;
    --color-on-primary: #ffffff;
    --color-link: #789df9;
    --color-success: #60b876;
    --color-warning: #e9b366;
    --color-danger: #f67368;
  }
}

